                        return (pos < buf.length) ? (buf[pos++] & 0xff) : -1;
                    }

                    @Override
                    public int read(byte[] b, int off, int len) {
                        if (pos >= buf.length) {
                            return -1;
                        }
                        int avail = buf.length - pos;
                        if (len > avail) {
                            len = avail;
                        }
                        if (len <= 0) {
                            return 0;
                        }
                        System.arraycopy(buf, pos, b, off, len);
                        pos += len;
                        return len;
