                        if (n < k) {
                            k = n < 0 ? 0 : n;
                        }
                        pos += k;
                        return k;
                    }

                    @Override
                    public int available() {
                        return buf.length - pos;
                    }

                    @Override
                    public void mark(int readAheadLimit) {
                        mark = pos;
                    }

                    @Override
