    private int readWithUpdate() throws IOException {
        final int target = this.target.read();
        eofSeen = target == EOF;
        if (eofSeen) {
            return target;
        }
        slashRSeen = target == CR;
        slashNSeen = target == LF;
        return target;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public int read() throws IOException {
        if (eofSeen) {
            return eofGame();
        } else if (injectSlashN) {
            injectSlashN = false;
            return LF;
        } else {
            final boolean prevWasSlashR = slashRSeen;
            final int target = readWithUpdate();
            if (eofSeen) {
                return eofGame();
            }
            if (target == LF) {
                if (!prevWasSlashR) {
                    injectSlashN = true;
                    return CR;
                }
            }
            return target;
        }
    }

    /**
     * Handles the EOF-handling at the end of the stream
     * @return The next char to output to the stream
     */
    private int eofGame() {
        if (!ensureLineFeedAtEndOfFile) {
            return EOF;
        }
        if (!slashNSeen && !slashRSeen) {
            slashRSeen = true;
            return CR;
        }
        if (!slashNSeen) {
            slashRSeen = false;
            slashNSeen = true;
            return LF;
        }
        return EOF;
    }

    /**
     * Closes the stream. Also closes the underlying stream.
     * @throws IOException upon error
     */
    @Override
    public void close() throws IOException {
        super.close();
        target.close();
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public synchronized void mark(final int readlimit) {
        throw new UnsupportedOperationException("Mark not supported");
    }
}

