     * {@code boolean java.nio.file.Files.isSymbolicLink(Path path)}
     * @param file the file to check
     * @return true if the file is a Symbolic Link
     * @since 2.0
     */
    public static boolean isSymlink(final File file) {
        if (file == null) {
